-- Generated by `chainindex dbt` from chains/base.yaml and abis/AerodromePoolFactory.json. Do not edit: change the chain file or ABI and regenerate.
-- PoolCreated(address,address,bool,address,uint256)
{{ config(
    materialized='view',
    schema='events_base',
    alias='aerodrome_pool_factory__pool_created',
    tags=['chains', 'chain_base'],
) }}

select
    toUInt64(8453) as chain_id,
    address,
    block_number,
    block_time,
    block_hash,
    transaction_hash,
    transaction_index,
    log_index,
    inserted_at,
    concat('0x', substring(substring(topic1, 3, 64), 25, 40)) as token0,
    concat('0x', substring(substring(topic2, 3, 64), 25, 40)) as token1,
    toBool(reinterpretAsUInt256(reverse(unhex(substring(topic3, 3, 64)))) != 0) as stable,
    concat('0x', substring(substring(data, 3, 64), 25, 40)) as pool,
    reinterpretAsUInt256(reverse(unhex(substring(data, 67, 64)))) as pool_count
from {{ source('chain_base', 'logs') }}
where topic0 = '0x2128d88d14c80cb081c1252a5acff7a264671bf199ce226b53788fb26065005e'
  and address in (select address from {{ ref('base__contracts') }} where contract = 'aerodrome_pool_factory')
  and (block_number, block_hash) not in (
    select block_number, block_hash from {{ source('chain_base', 'orphaned_blocks') }}
  )
